/* ===================== BÀI 20 · Endianness, alignment và serialization ===================== */
/* Bài 20 · Endianness, alignment và serialization (CM02.06) — sinh bởi tools/author/maytinh/m20.py, không sửa tay.
   Phòng mô phỏng từng bước và bài tập chấm tự động; phần chữ bài học ở lesson.html (nội dung bảo vệ). */
makeMtLab(document.getElementById("lab-l20"),{id:"l20",scenarios:[{"label": "Ví dụ: 0x12345678 trong bộ nhớ", "note": "So sánh little-endian và big-endian.", "steps": [{"t": "Số 32 bit 0x12345678 cần 4 byte", "html": "<p class=\"mt-calc\">Byte cao nhất (MSB) = 0x12 · byte thấp nhất (LSB) = 0x78 · ghi vào các địa chỉ 1000–1003<\/p>", "say": "<p>Bộ nhớ đánh địa chỉ theo byte (Bài 15). Câu hỏi: byte nào nằm ở địa chỉ nhỏ nhất?<\/p>"}, {"t": "Little-endian: byte thấp trước → 78 56 34 12", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Địa chỉ<\/th><th scope=\"col\">1000<\/th><th scope=\"col\">1001<\/th><th scope=\"col\">1002<\/th><th scope=\"col\">1003<\/th><\/tr><\/thead><tbody><tr><td>Byte<\/td><td class=\"new\">78<\/td><td>56<\/td><td>34<\/td><td>12<\/td><\/tr><\/tbody><\/table>", "ask": {"q": "Little-endian: ở địa chỉ nhỏ nhất (1000) là byte nào của 0x12345678?", "o": ["12", "78", "34"], "a": 1}, "say": "<p>Little-endian: byte thấp nhất ở địa chỉ nhỏ nhất. Máy x86 dùng thứ tự này; phần lớn hệ thống ARM cũng chạy ở little-endian.<\/p>"}, {"t": "Big-endian: byte cao trước → 12 34 56 78", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Địa chỉ<\/th><th scope=\"col\">1000<\/th><th scope=\"col\">1001<\/th><th scope=\"col\">1002<\/th><th scope=\"col\">1003<\/th><\/tr><\/thead><tbody><tr><td>Byte<\/td><td class=\"new\">12<\/td><td>34<\/td><td>56<\/td><td>78<\/td><\/tr><\/tbody><\/table>", "say": "<p>Big-endian: byte cao nhất ở địa chỉ nhỏ nhất, giống cách ta viết số. Giao thức mạng TCP/IP dùng thứ tự này, gọi là thứ tự byte mạng.<\/p>"}]}, {"label": "Ví dụ: Căn lề và byte đệm trong struct", "note": "Đổi thứ tự trường làm struct gọn hơn.", "steps": [{"t": "Căn lề: int 4 byte nằm ở địa chỉ chia hết cho 4", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Kiểu<\/th><th scope=\"col\">Kích thước<\/th><th scope=\"col\">Căn lề thường gặp<\/th><\/tr><\/thead><tbody><tr><td>char<\/td><td>1<\/td><td>1<\/td><\/tr><tr><td>int (32 bit)<\/td><td>4<\/td><td>4<\/td><\/tr><tr><td>double<\/td><td>8<\/td><td>8<\/td><\/tr><\/tbody><\/table>", "say": "<p>Căn lề: CPU đọc dữ liệu nhanh và đơn giản nhất khi địa chỉ chia hết cho kích thước. Một số kiến trúc báo lỗi khi đọc lệch, số khác chậm hơn. Bảng là giá trị thường gặp trên x86-64 và ARM64.<\/p>"}, {"t": "struct { char a; int b; char c; }: 12 byte", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Byte<\/th><th scope=\"col\">0<\/th><th scope=\"col\">1<\/th><th scope=\"col\">2<\/th><th scope=\"col\">3<\/th><th scope=\"col\">4<\/th><th scope=\"col\">5<\/th><th scope=\"col\">6<\/th><th scope=\"col\">7<\/th><th scope=\"col\">8<\/th><th scope=\"col\">9<\/th><th scope=\"col\">10<\/th><th scope=\"col\">11<\/th><\/tr><\/thead><tbody><tr><td>Trường<\/td><td class=\"new\">a<\/td><td class=\"dim\">đệm<\/td><td class=\"dim\">đệm<\/td><td class=\"dim\">đệm<\/td><td class=\"new\">b<\/td><td class=\"new\">b<\/td><td class=\"new\">b<\/td><td class=\"new\">b<\/td><td class=\"new\">c<\/td><td class=\"dim\">đệm<\/td><td class=\"dim\">đệm<\/td><td class=\"dim\">đệm<\/td><\/tr><\/tbody><\/table><p class=\"mt-calc\">b phải bắt đầu ở byte 4 → 3 byte đệm; tổng kích thước làm tròn lên bội 4 → thêm 3 byte đệm cuối<\/p>", "ask": {"q": "Trong struct {char a; int b; char c;}, trường b bắt đầu ở byte thứ mấy (giả định int căn lề 4)?", "o": ["1", "4", "2"], "a": 1}}, {"t": "Đổi thứ tự trường: { int b; char a; char c; } chỉ còn 8 byte", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Byte<\/th><th scope=\"col\">0<\/th><th scope=\"col\">1<\/th><th scope=\"col\">2<\/th><th scope=\"col\">3<\/th><th scope=\"col\">4<\/th><th scope=\"col\">5<\/th><th scope=\"col\">6<\/th><th scope=\"col\">7<\/th><\/tr><\/thead><tbody><tr><td>Trường<\/td><td class=\"new\">b<\/td><td class=\"new\">b<\/td><td class=\"new\">b<\/td><td class=\"new\">b<\/td><td class=\"new\">a<\/td><td class=\"new\">c<\/td><td class=\"dim\">đệm<\/td><td class=\"dim\">đệm<\/td><\/tr><\/tbody><\/table>", "say": "<p>Cùng dữ liệu, ít byte đệm hơn. Xếp trường từ lớn tới nhỏ thường tiết kiệm bộ nhớ. Kích thước cụ thể phụ thuộc trình biên dịch và ABI; kiểm tra bằng sizeof.<\/p>"}]}, {"label": "Ví dụ: Gửi số 300 theo thứ tự byte mạng", "note": "Big-endian trên dây, đổi sang thứ tự của máy khi nhận.", "steps": [{"t": "Gửi số 300 (16 bit không dấu) qua mạng", "html": "<p class=\"mt-calc\">300 = 0x012C · giao thức quy định big-endian → gửi <b>01 2C<\/b><\/p>", "say": "<p>Tuần tự hóa: biến dữ liệu trong bộ nhớ thành dãy byte có định dạng rõ ràng để lưu hoặc gửi đi.<\/p>"}, {"t": "Bên nhận little-endian đọc thẳng vào biến: 11 265", "html": "<p class=\"mt-calc\">2C 01 theo thứ tự little-endian → 0x2C01 = <b>11 265<\/b> ✗<\/p>", "ask": {"q": "Byte nhận được 01 2C. Đọc theo little-endian (không đổi thứ tự) ra giá trị nào?", "o": ["300", "11 265", "44"], "a": 1}}, {"t": "Sửa: đổi từ thứ tự mạng sang thứ tự máy", "html": "<p class=\"mt-calc\">Dùng hàm đổi thứ tự byte (ví dụ ntohs trong thư viện socket) hoặc ghép từng byte: (b0 × 256) + b1 = 300 ✓<\/p>", "say": "<p>Quy tắc của tuần tự hóa: mỗi trường phải có kích thước, có dấu hay không, thứ tự byte và (với chữ) bảng mã (Bài 18) được ghi rõ. Định dạng văn bản như JSON tránh được thứ tự byte nhưng tốn chỗ hơn.<\/p>"}]}, {"label": "Lỗi: Đọc byte little-endian như big-endian", "note": "0x12345678 thành 0x78563412.", "steps": [{"t": "Máy A (little-endian) ghi 0x12345678 ra tệp", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Địa chỉ<\/th><th scope=\"col\">1000<\/th><th scope=\"col\">1001<\/th><th scope=\"col\">1002<\/th><th scope=\"col\">1003<\/th><\/tr><\/thead><tbody><tr><td>Byte<\/td><td>78<\/td><td>56<\/td><td>34<\/td><td>12<\/td><\/tr><\/tbody><\/table>", "say": "<p>Chương trình ghi thẳng 4 byte trong bộ nhớ ra tệp, không quy định thứ tự byte.<\/p>"}, {"t": "Máy B đọc 4 byte theo big-endian", "html": "<p class=\"mt-calc\">78 56 34 12 đọc big-endian = <b>0x78563412<\/b> = 2 018 915 346<\/p>", "ask": {"q": "Byte 78 56 34 12 được đọc theo big-endian. Giá trị là bao nhiêu (hex)?", "o": ["0x12345678", "0x78563412", "0x56781234"], "a": 1}}, {"t": "Sửa: quy định thứ tự byte trong định dạng", "html": "<p class=\"mt-calc\">Định dạng tệp / giao thức phải ghi rõ: “số 32 bit, big-endian”; người ghi và người đọc đều đổi đúng thứ tự<\/p>", "say": "<p>Lỗi này không làm chương trình dừng; nó chỉ cho số sai. Vì vậy nó hay lọt qua kiểm thử nếu cả hai đầu cùng một loại máy.<\/p>"}]}, {"label": "Bẫy: Float 32 bit qua hai thanh ghi Modbus", "note": "Thứ tự thanh ghi tùy hãng; đọc nhầm cho giá trị vô lý.", "steps": [{"t": "Float32 25,5 = 0x41CC0000 cần hai thanh ghi 16 bit", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Thanh ghi<\/th><th scope=\"col\">Nội dung<\/th><\/tr><\/thead><tbody><tr><td>Thanh ghi 1<\/td><td>0x41CC<\/td><\/tr><tr><td>Thanh ghi 2<\/td><td>0x0000<\/td><\/tr><\/tbody><\/table>", "say": "<p>Modbus quy định mỗi thanh ghi 16 bit gửi byte cao trước, nhưng không quy định thanh ghi nào chứa nửa cao của giá trị 32 bit; các hãng làm khác nhau.<\/p>"}, {"t": "Thiết bị gửi nửa thấp trước: 0x0000, 0x41CC", "html": "<p class=\"mt-calc\">Ghép theo thứ tự nhận: 0x000041CC → float32 ≈ <b>2,36 × 10⁻⁴¹<\/b> ✗<\/p>", "ask": {"q": "Đọc nhầm thứ tự hai thanh ghi của số float 25,5. Kết quả thường thế nào?", "o": ["25,5 chính xác", "Một giá trị vô lý (rất nhỏ, rất lớn hoặc NaN)", "Chương trình báo lỗi rõ ràng"], "a": 1}}, {"t": "Sửa: tra tài liệu thiết bị về thứ tự thanh ghi", "html": "<p class=\"mt-calc\">Tài liệu thường ghi “word order”, “byte swap”, “ABCD / CDAB”; thử với một giá trị đã biết trước khi chạy thật<\/p>", "say": "<p>Mẹo kiểm tra: cho thiết bị gửi một giá trị đã biết (ví dụ 25,5) và so mẫu byte nhận được. Các khóa về truyền thông công nghiệp của AMTS học Modbus kỹ hơn.<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l20"),"l20",[{"kind": "num", "t": "Byte ở địa chỉ nhỏ nhất", "d": "<p>Ghi giá trị byte ở hệ 10.<\/p>", "items": [{"q": "0x0A0B0C0D lưu little-endian: byte ở địa chỉ nhỏ nhất?", "a": 13}, {"q": "0x0A0B0C0D lưu big-endian: byte ở địa chỉ nhỏ nhất?", "a": 10}, {"q": "Số 16 bit 0x1234 lưu little-endian: byte ở địa chỉ lớn hơn?", "a": 18}, {"q": "Số 258 (16 bit) lưu big-endian: byte ở địa chỉ nhỏ nhất?", "a": 1}], "hints": ["Little-endian: byte thấp (cuối số hex) trước.", "Big-endian: byte cao (đầu số hex) trước.", "258 = 0x0102."], "why": "LE: 0x0D = 13; BE: 0x0A = 10; 0x1234 LE là 34 12 nên byte sau là 0x12 = 18; 258 = 0x0102, BE bắt đầu bằng 0x01 = 1."}, {"kind": "num", "t": "Đọc dãy byte", "d": "<p>Ghi giá trị số không dấu ở hệ 10.<\/p>", "items": [{"q": "Byte 01 2C đọc big-endian", "a": 300}, {"q": "Byte 01 2C đọc little-endian", "a": 11265}, {"q": "Byte E8 03 đọc little-endian", "a": 1000}, {"q": "Byte 00 00 01 00 đọc big-endian", "a": 256}], "hints": ["Big-endian: byte đầu × 256 + byte sau.", "Little-endian: byte sau × 256 + byte đầu.", "0x03E8 = 1 000."], "why": "0x012C = 300; 0x2C01 = 11 265; E8 03 LE = 0x03E8 = 1 000; 0x00000100 = 256."}, {"kind": "num", "t": "Kích thước struct", "d": "<p>Giả định: char 1 byte, short 2 byte căn lề 2, int 4 byte căn lề 4; kích thước struct làm tròn lên bội số căn lề lớn nhất của các trường.<\/p>", "items": [{"q": "struct { char a; int b; char c; }", "a": 12, "unit": "byte"}, {"q": "struct { int b; char a; char c; }", "a": 8, "unit": "byte"}, {"q": "struct { char a; short s; }", "a": 4, "unit": "byte"}, {"q": "Vị trí (byte) của trường c trong struct { char a; int b; char c; }", "a": 8}], "hints": ["Mỗi trường bắt đầu ở địa chỉ chia hết cho căn lề của nó.", "Sau trường cuối, thêm đệm để tổng chia hết cho căn lề lớn nhất.", "char a ở 0, short s phải bắt đầu ở 2."], "why": "12 byte (a, 3 đệm, b, c, 3 đệm); 8 byte; char + 1 đệm + short = 4 byte; c ở byte 8."}]);

makeQuiz("quiz20","score20",[{"q": "Máy little-endian lưu 0xAABBCCDD. Byte ở địa chỉ nhỏ nhất là gì?", "o": ["AA", "DD", "BB", "CC"], "a": 1, "e": "Little-endian đặt byte thấp nhất (DD) trước."}, {"q": "“Thứ tự byte mạng” (network byte order) của TCP/IP là gì?", "o": ["Little-endian", "Tùy máy gửi", "Big-endian", "Không có quy định"], "a": 2, "e": "Giao thức TCP/IP dùng big-endian; máy little-endian phải đổi khi gửi và nhận."}, {"q": "Vì sao struct { char a; int b; char c; } thường dài 12 byte chứ không phải 6?", "o": ["Vì char dài 4 byte", "Vì trình biên dịch thêm byte đệm để int căn lề 4 và kích thước là bội 4", "Vì có thêm thông tin kiểu", "Vì int dài 8 byte"], "a": 1, "e": "3 byte đệm trước b và 3 byte đệm cuối. Đổi thứ tự trường có thể giảm còn 8."}, {"q": "Một giá trị float đọc từ thiết bị Modbus ra 2,36 × 10⁻⁴¹ thay vì 25,5. Nguyên nhân khả dĩ nhất là gì?", "o": ["Thiết bị hỏng", "Nhiễu điện", "Đọc sai thứ tự hai thanh ghi 16 bit", "Thiếu điện trở kéo lên"], "a": 2, "e": "Giá trị vô lý (rất nhỏ, rất lớn, NaN) là dấu hiệu điển hình của sai thứ tự byte hoặc thanh ghi."}, {"q": "Vì sao không nên ghi nguyên vùng nhớ của một struct ra tệp để máy khác đọc?", "o": ["Vì tệp sẽ quá lớn", "Vì byte đệm, thứ tự byte và kích thước kiểu có thể khác giữa các máy", "Vì struct không thể ghi ra tệp", "Vì sẽ mất bảng mã"], "a": 1, "e": "Hãy tuần tự hóa từng trường theo định dạng đã quy định."}]);

